using System.Globalization;using System.Text;using System.Security.Cryptography;
namespace BureauSync.Api;
public class CsvValidator { public (List<SubmissionRecord>,string) Validate(Stream stream,Lender? lender=null) { using var reader=new StreamReader(stream,Encoding.UTF8,true,leaveOpen:true);var text=reader.ReadToEnd();var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));var lines=text.Replace("\r\n","\n").Split('\n',StringSplitOptions.RemoveEmptyEntries);if(lines.Length<2)throw new InvalidOperationException("CSV needs a header and at least one record.");var h=Split(lines[0]).Select(x=>x.Trim().ToLowerInvariant()).ToArray();var req=new[]{"lender_id","borrower_name","identity_id","loan_account_no","loan_amount","outstanding_balance","status","disbursement_date","due_date","repayment_date"};var missing=req.Except(h).ToArray();if(missing.Length>0)throw new InvalidOperationException("Missing columns: "+string.Join(", ",missing));var validLenderIds=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(lender!=null){if(!string.IsNullOrWhiteSpace(lender.Code))validLenderIds.Add(lender.Code);if(!string.IsNullOrWhiteSpace(lender.SwiftBic))validLenderIds.Add(lender.SwiftBic);if(!string.IsNullOrWhiteSpace(lender.CbnLicense))validLenderIds.Add(lender.CbnLicense);if(!string.IsNullOrWhiteSpace(lender.Lei))validLenderIds.Add(lender.Lei);if(!string.IsNullOrWhiteSpace(lender.CustomId))validLenderIds.Add(lender.CustomId);}var result=new List<SubmissionRecord>();var accounts=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);for(int i=1;i<lines.Length;i++){var vals=Split(lines[i]);var d=h.Select((key,n)=>new KeyValuePair<string,string>(key,n<vals.Count?vals[n].Trim():"" )).ToDictionary(x=>x.Key,x=>x.Value);var r=new SubmissionRecord{RowNumber=i+1,LenderCode=d["lender_id"],BorrowerName=d["borrower_name"],IdentityId=d["identity_id"],AccountNumber=d["loan_account_no"],LoanStatus=d["status"].ToUpperInvariant(),LoanAmount=Money(d["loan_amount"]),OutstandingBalance=Money(d["outstanding_balance"])};Required(r,"lender_id",r.LenderCode);if(lender!=null&&!string.IsNullOrWhiteSpace(r.LenderCode)&&!validLenderIds.Contains(r.LenderCode))Error(r,"UNKNOWN_LENDER_ID","lender_id",$"Lender ID '{r.LenderCode}' does not match the selected lender's registered IDs.","Use one of the lender's registered IDs: internal code, SWIFT/BIC, CBN License, LEI, or Custom ID.");Required(r,"borrower_name",r.BorrowerName);Required(r,"identity_id",r.IdentityId);Required(r,"loan_account_no",r.AccountNumber);if(r.LoanAmount is null||r.LoanAmount<=0)Error(r,"INVALID_LOAN_AMOUNT","loan_amount","Loan amount must be positive.","Provide a positive amount.");if(r.OutstandingBalance is null||r.OutstandingBalance<0)Error(r,"INVALID_BALANCE","outstanding_balance","Outstanding balance cannot be negative.","Correct balance.");if(r.LoanAmount is not null&&r.OutstandingBalance is not null&&r.OutstandingBalance>r.LoanAmount)Error(r,"BALANCE_EXCEEDS_LOAN","outstanding_balance","Balance exceeds original loan.","Correct balance or loan amount.");if(!new[]{"ACTIVE","REPAID","SETTLED","DEFAULTED"}.Contains(r.LoanStatus))Error(r,"INVALID_STATUS","status","Status is invalid.","Use ACTIVE, REPAID, SETTLED, or DEFAULTED.");if((r.LoanStatus=="REPAID"||r.LoanStatus=="SETTLED")&&r.OutstandingBalance!=0)Error(r,"REPAYMENT_CONFLICT","outstanding_balance","Repaid or settled loan must have zero balance.","Correct the status or balance.");if(!DateOnly.TryParseExact(d["disbursement_date"],"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out _))Error(r,"INVALID_DATE","disbursement_date","Date must be YYYY-MM-DD.","Correct date.");if(!DateOnly.TryParseExact(d["due_date"],"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out _))Error(r,"INVALID_DATE","due_date","Date must be YYYY-MM-DD.","Correct date.");if((r.LoanStatus=="REPAID"||r.LoanStatus=="SETTLED")&&string.IsNullOrWhiteSpace(d["repayment_date"]))Warn(r,"MISSING_REPAYMENT_DATE","repayment_date","Repayment date needs review.","Add repayment date.");if(!string.IsNullOrWhiteSpace(r.AccountNumber)){if(accounts.TryGetValue(r.AccountNumber,out var row))Error(r,"DUPLICATE_ACCOUNT","loan_account_no","Account duplicates row "+row+".","Remove or correct duplicate.");else accounts[r.AccountNumber]=r.RowNumber;}r.Outcome=r.Issues.Any(x=>x.Severity=="Error")?"Rejected":r.Issues.Any()?"Review":"Ready";result.Add(r);}return(result,hash); } static List<string> Split(string s){var a=new List<string>();var b=new StringBuilder();bool q=false;for(int i=0;i<s.Length;i++){if(s[i]=='"')q=!q;else if(s[i]==','&&!q){a.Add(b.ToString());b.Clear();}else b.Append(s[i]);}a.Add(b.ToString());return a;}static decimal? Money(string s)=>decimal.TryParse(s,NumberStyles.Number,CultureInfo.InvariantCulture,out var v)?v:null;static void Required(SubmissionRecord r,string f,string v){if(string.IsNullOrWhiteSpace(v))Error(r,"REQUIRED_FIELD",f,"Required field is missing.","Supply field and resubmit.");}static void Error(SubmissionRecord r,string c,string f,string m,string a)=>r.Issues.Add(new ValidationIssue{RuleCode=c,Field=f,Severity="Error",Message=m,SuggestedAction=a});static void Warn(SubmissionRecord r,string c,string f,string m,string a)=>r.Issues.Add(new ValidationIssue{RuleCode=c,Field=f,Severity="Warning",Message=m,SuggestedAction=a}); }
